/// <summary>
///     AVA <c>avaGetInquirerInfo</c> method.
///     returns a list of inquirers with address and name for current ContactPersonId
/// </summary>
/// <param name="_languageId">
///     <c>LanguageId</c> as type
/// </param>
/// <returns>
///     <c>str</c> as return value
/// </returns>
public str avaGetInquirerInfo(LanguageId _languageId = CompanyInfo::find().LanguageId)
{
    str inquirerInfo;
    str locTmpStr;
    //ContactPerson avaContact = ContactPerson::find(this.ContactPersonId);
    LogisticsPostalAddress avaAddress = DirParty::primaryPostalAddress(this.dirPartyTablePrefered().RecId);
    /*
    inquirerInfo = strFmt('%1, %2, %3, %4 %5'
        , this.DirPartyTable_FK().Name
        , avaContact.personName()
        , strReplace(avaAddress.Street, '\n', ', ')
        , avaAddress.ZipCode
        , avaAddress.City);
    */

    locTmpStr = this.DirPartyTable_FK().Name;
    if(inquirerInfo && locTmpStr)
    {
        inquirerInfo += ', ';
    }
    inquirerInfo += locTmpStr;

    locTmpStr = ContactPerson::avaGetContactNameWithTitle(this.ContactPersonId, _languageId);
    if(inquirerInfo && locTmpStr)
    {
        inquirerInfo += ', ';
    }
    inquirerInfo += locTmpStr;

    locTmpStr = strReplace(avaAddress.Street, '\n', ', ');
    if(inquirerInfo && locTmpStr)
    {
        inquirerInfo += ', ';
    }
    inquirerInfo += locTmpStr;

    locTmpStr = avaAddress.ZipCode + ' ' + avaAddress.City;
    if(inquirerInfo && locTmpStr)
    {
        inquirerInfo += ', ';
    }
    inquirerInfo += locTmpStr;

    return inquirerInfo;
}
